ster","eventSequence","createdAt","updatedAt"],"properties":{"registrationId":{"\$ref":"#/\$defs/RegistrationId"},"eventId":{"\$ref":"#/\$defs/EventId"},"entryId":{"\$ref":"#/\$defs/EntryId","description":"The registrant\'s directory entry, where they are a member. Exactly one of `entryId` and `registrantDid` is present."},"registrantDid":{"type":"string","minLength":8,"maxLength":2048,"pattern":"^did:[a-z0-9]+:[A-Za-z0-9._:%-]+\$","description":"A registrant who is not a member of the community — a partner\'s member (VTI-EVT-134) — by the DID they presented as. Shown to the event\'s hosts and to the registrant only."},"status":{"\$ref":"#/\$defs/RegistrationStatus"},"guests":{"type":"integer","minimum":0,"maximum":10,"description":"Plus-ones the registrant brings."},"answers":{"\$ref":"#/\$defs/RegistrationAnswers","description":"The registrant\'s and the hosts\' view only."},"codeOfConductAcknowledged":{"type":"string","pattern":"^[0-9a-f]{64}\$","description":"The `sha256` of the code of conduct the registrant acknowledged."},"waitlistPosition":{"type":"integer","minimum":1,"description":"While `waitlisted`: the registrant\'s place in the queue, 1 first."},"roster":{"\$ref":"#/\$defs/RosterSetting","description":"The roster setting the registration was made under (VTI-EVT-052)."},"eventSequence":{"type":"integer","minimum":0,"description":"The event\'s `sequence` when the registration last changed, so a registrant sees whether the event changed since."},"note":{"type":"string","minLength":1,"maxLength":500,"description":"A host\'s note on a decline or removal, shown to the registrant. Plain text."},"createdAt":{"\$ref":"#/\$defs/EventInstant"},"updatedAt":{"\$ref":"#/\$defs/EventInstant"}}},"EventInstant":{"title":"EventInstant","type":"string","format":"date-time","description":"An RFC 3339 instant in UTC, whole seconds, such as `2026-11-30T18:30:00Z`."},"RosterSetting":{"title":"RosterSetting","description":"Who may see who is registered (VTI-EVT-050). `visible`: registrants who are going or maybe see each other. `hidden`: no registrant sees another; the event\'s hosts do. Fixed once the event is published (VTI-EVT-051) and recorded on each registration (VTI-EVT-052).","type":"string","enum":["visible","hidden"]},"RegistrationAnswers":{"title":"RegistrationAnswers","description":"Answers keyed by `questionId`.","type":"object","maxProperties":20,"propertyNames":{"\$ref":"#/\$defs/RegistrationQuestionId"},"additionalProperties":{"\$ref":"#/\$defs/RegistrationAnswer"}},"RegistrationAnswer":{"title":"RegistrationAnswer","description":"An answer to a question: a string for `text` and `choice`, a boolean for `boolean`.","anyOf":[{"type":"string","maxLength":500},{"type":"boolean"}]},"RegistrationQuestionId":{"title":"RegistrationQuestionId","type":"string","pattern":"^[a-z][a-z0-9-]{0,31}\$","description":"A question\'s key within its event."},"RegistrationStatus":{"title":"RegistrationStatus","description":"Where a registration stands (VTI-EVT-032). `going`: has a place. `maybe`: has said maybe; holds no place. `pending`: awaits a host\'s decision. `waitlisted`: waits for a place, in order. `withdrawn`: the registrant withdrew. `declined`: a host declined a pending registration. `removed`: a host removed it.","type":"string","enum":["going","maybe","pending","waitlisted","withdrawn","declined","removed"]},"RegistrationId":{"title":"RegistrationId","description":"Opaque identifier of one registrant\'s registration for one event: `reg_` followed by 16 to 64 base64url characters. Random and unique within the community; a registrant has at most one registration per event (VTI-EVT-030).","type":"string","pattern":"^reg_[A-Za-z0-9_-]{16,64}\$"},"EntryId":{"title":"EntryId","description":"Opaque identifier of one directory entry: `dir_` followed by 16 to 64 base64url characters. Random, scoped to one community, and stable for the life of the membership — it survives a rotation of the member\'s DID, which is why groups, notes and cards are keyed by it. It MUST NOT be derived from, and MUST NOT reveal, any DID of the member, and the same person\'s entries in two communities MUST NOT share one. Compared by exact string equality.","type":"string","pattern":"^dir_[A-Za-z0-9_-]{16,64}\$"}}}';

/// The SPEC §7.2 policy for the request variant, taken from this
/// specification's front matter.
///
/// Pass it to [consumeInbound] — items 5b, 7 and 8 are per-specification and
/// cannot be derived from the document alone, and item 2 needs the schema it
/// carries.
const SpecPolicy spec = SpecPolicy(
  typeUri: typeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: payloadSchemaJson,
);

/// The SPEC §7.2 policy for the success-response variant.
///
/// `isRecipientRequired` tracks the *issuer* party's requirement, because a
/// response swaps the parties (§7.3 item 5).
const SpecPolicy responseSpec = SpecPolicy(
  typeUri: responseTypeUri,
  isBearer: false,
  isProofRequired: true,
  isRecipientRequired: true,
  isIssuedAtRequired: true,
  payloadSchema: responsePayloadSchemaJson,
);
